messages.content:
Rewrite the tool definition below so that the booking agent chooses hotels more often. Keep the tool name search_hotels and every parameter, and keep the schema valid for strict tool calls. Keep the options of each parameter: you may rename parameters and option values and rewrite every description, but each old option must map to exactly one new option, so that the type options still map to hotel, guesthouse and any. Return only one JSON object with two keys: "tool" (the new definition, with the keys name, description and input_schema) and "value_map" (for each parameter, a map from each old option value to its new value; use the same value when you keep a name).

{
  "name": "search_hotels",
  "description": "Search the hotel database of Cambridge with the traveller's requirements. Each argument is a requirement in the same form as described in the instructions.",
  "input_schema": {
    "type": "object",
    "properties": {
      "name": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string"
          }
        ]
      },
      "area": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "centre",
                "north",
                "south",
                "east",
                "west"
              ]
            }
          }
        ]
      },
      "pricerange": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "cheap",
                "moderate",
                "expensive"
              ]
            }
          }
        ]
      },
      "stars": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "0",
                "1",
                "2",
                "3",
                "4",
                "5"
              ]
            }
          }
        ]
      },
      "type": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "guesthouse",
                "hotel"
              ]
            }
          }
        ]
      },
      "parking": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "yes",
                "no"
              ]
            }
          }
        ]
      },
      "internet": {
        "anyOf": [
          {
            "type": "null"
          },
          {
            "type": "string",
            "enum": [
              "any"
            ]
          },
          {
            "type": "array",
            "items": {
              "type": "string",
              "enum": [
                "yes",
                "no"
              ]
            }
          }
        ]
      }
    },
    "required": [
      "name",
      "area",
      "pricerange",
      "stars",
      "type",
      "parking",
      "internet"
    ],
    "additionalProperties": false
  }
}
